set-variable.value:
@{
      var cand = new System.Collections.Generic.HashSet<string>(StringComparer.OrdinalIgnoreCase);
      var cfg = JObject.Parse((string)context.Variables["aclJson"]);
      foreach (var e in (JArray)(cfg["acl"] ?? new JArray())) {
          if ((string)e["match"]["type"] == "group") { cand.Add((string)e["match"]["value"]); }
      }
      var jwt = (Jwt)context.Variables["jwt"];
      var claimGroups = jwt.Claims.ContainsKey("groups") ? jwt.Claims["groups"] : new string[0];
      foreach (var g in claimGroups) { cand.Remove(g); }
      return new JArray(cand.Take(20)).ToString(Newtonsoft.Json.Formatting.None);
  }

@{
      var set = new System.Collections.Generic.HashSet<string>(StringComparer.OrdinalIgnoreCase);
      var jwt = (Jwt)context.Variables["jwt"];
      if (jwt.Claims.ContainsKey("groups")) { foreach (var g in jwt.Claims["groups"]) { set.Add(g); } }
      if (context.Variables.ContainsKey("graphGroups")) { foreach (var t in JArray.Parse((string)context.Variables["graphGroups"])) { set.Add((string)t); } }
      return new JArray(set).ToString(Newtonsoft.Json.Formatting.None);
  }

@{
      var cfg    = JObject.Parse((string)context.Variables["aclJson"]);
      var jwt    = (Jwt)context.Variables["jwt"];
      var roles  = jwt.Claims.ContainsKey("roles")  ? jwt.Claims["roles"]  : new string[0];
      var groups = JArray.Parse((string)context.Variables["effectiveGroups"]).Select(t => (string)t).ToArray();
      var scopes = (jwt.Claims.ContainsKey("scp") ? string.Join(" ", jwt.Claims["scp"]) : "").Split(' ');
      var matched = new JArray(); var allow = new JArray(); var deny = new JArray(); var all = false; var i = 0;
      foreach (var e in (JArray)(cfg["acl"] ?? new JArray())) {
          var mt = (string)e["match"]["type"]; var mv = (string)e["match"]["value"];
          var hit = (mt == "any")
                 || (mt == "role"  && roles.Contains(mv, StringComparer.OrdinalIgnoreCase))
                 || (mt == "group" && groups.Contains(mv, StringComparer.OrdinalIgnoreCase))
                 || (mt == "scope" && scopes.Contains(mv, StringComparer.OrdinalIgnoreCase));
          if (hit) {
              matched.Add(i);
              var a = e["allow"];
              if (a != null && a.Type == JTokenType.String && (string)a == "all") { all = true; }
              else if (a != null) { foreach (var t in (JArray)a) { allow.Add((string)t); } }
              if (e["deny"] != null) { foreach (var t in (JArray)e["deny"]) { deny.Add((string)t); } }
          }
          i++;
      }
      return new JObject { ["matched"] = matched, ["all"] = all, ["allow"] = allow, ["deny"] = deny }.ToString(Newtonsoft.Json.Formatting.None);
  }
